// 本人收件/交付记录使用实际观察者索引，不扫描全世界信件，更不展示未获送达消息的远方发件人。
#include "task_message_handoff.hpp"
#include "task_message_report.hpp"
namespace hanmo::resident {
Outcome<BoundaryValue> query_task_message_handoffs(const CommonStore& common,const TaskState& tasks,const TaskCatalog& catalog,const CommonCatalog& shared,const TaskMessageHandoffState& state,Integer cursor){
    using V=BoundaryValue;const auto& observer=common.state().metadata.player_actor_id;if(!common.actor(observer))return {false,{},common_failure("UnknownPlayer").error};if((state.version!=1&&state.version!=2&&state.version!=3&&state.version!=4))return {false,{},common_failure("UnsupportedTaskMessageHandoffVersion").error};
    const auto found=state.observed_by.find(observer);const auto handoff_count=found==state.observed_by.end()?0:found->second.size();const auto reported=state.reports_observed_by.find(observer);const auto report_count=(state.version==2||state.version==3||state.version==4)&&reported!=state.reports_observed_by.end()?reported->second.size():0;const auto size=handoff_count+report_count;if(cursor<0||static_cast<std::size_t>(cursor)>size)return {false,{},common_failure("InvalidMessageHandoffCursor").error};V::Array rows;Integer next=cursor;
    for(;static_cast<std::size_t>(next)<size&&rows.size()<16;++next){
        if(static_cast<std::size_t>(next)>=handoff_count){const auto& id=reported->second[static_cast<std::size_t>(next)-handoff_count];auto known=read_known_task_message_report(common,tasks,catalog,shared,state,observer,id);if(!known.ok)return {false,{},known.error};if(!known.value)return {false,{},common_failure("TaskMessageReportObserverIndexMismatch").error};const auto& report=*known.value;const auto& handoff=*state.receipts.find(report.handoff_fact_id);const auto& definition=*catalog.offers.find(handoff.offer_id);
            rows.push_back(boundary::obj({{"fact_id",V{report.fact_id}},{"task_id",V{report.task_id}},{"display_name",V{definition.display_name}},{"role",V{StableId{observer==report.report_actor_id?"heard_report":"reported"}}},{"carrier_actor_id",V{report.carrier_actor_id}},{"report_actor_id",V{report.report_actor_id}},{"handoff_fact_id",V{report.handoff_fact_id}},{"observed_tick",V{report.tick}},{"place_id",V{report.place_id}},{"explanation",V{StableId{"送信人已当面说明原信件交付结果，并按原任务办理结酬；未在场者不会自动获知这次返报。"}}}}));continue;}
        const auto& id=found->second[static_cast<std::size_t>(next)];auto known=read_known_task_message_handoff(common,tasks,catalog,shared,state,observer,id);if(!known.ok)return {false,{},known.error};if(!known.value)return {false,{},common_failure("TaskMessageHandoffObserverIndexMismatch").error};const auto& receipt=*known.value;const auto& definition=*catalog.offers.find(receipt.offer_id);
        const auto* task=tasks.tasks.find(receipt.task_id);bool unsupported_report=false;if((state.version==2||state.version==3||state.version==4)&&observer==receipt.carrier_actor_id&&task&&task->status=="success"&&definition.issuer.kind==Owner::Kind::organization){unsupported_report=true;if(reported!=state.reports_observed_by.end())for(const auto& report_id:reported->second){const auto* report=state.reports.find(report_id);if(report&&report->task_id==receipt.task_id){unsupported_report=false;break;}}}
        rows.push_back(boundary::obj({{"fact_id",V{receipt.fact_id}},{"task_id",V{receipt.task_id}},{"display_name",V{definition.display_name}},{"role",V{StableId{observer==receipt.recipient_actor_id?"received":"delivered"}}},{"carrier_actor_id",V{receipt.carrier_actor_id}},{"recipient_actor_id",V{receipt.recipient_actor_id}},{"item_id",V{receipt.item_id}},{"observed_tick",V{receipt.tick}},{"place_id",V{receipt.place_id}},{"explanation",V{StableId{unsupported_report?"原任务已按实际结果结酬；公约当场办理人缺少可复核历史指派来源，故未生成新的返报知情凭据。":"这是一份当场交接的信件记录；它不证明信中文字属实，也不会自动通知未在场的发件人。"}}}}));
    }
    StableId world_id;const char* digits="0123456789abcdef";for(auto byte:common.state().identity.world_id){world_id.push_back(digits[byte>>4]);world_id.push_back(digits[byte&15]);}
    V::Dict page{{"ok",V{true}},{"observer_actor_id",V{observer}},{"source_identity",boundary::obj({{"world_id",V{world_id}},{"execution_epoch",V{common.state().identity.execution_epoch}},{"revision",V{common.revision()}},{"tick",V{common.tick()}}})},{"cursor",V{cursor}},{"rows",V{std::move(rows)}}};if(static_cast<std::size_t>(next)<size)page.emplace_back("next_cursor",V{next});return {true,V{std::move(page)},{}};
}
}
